from copy import deepcopy
import pytest


def native_snapshot():
    # Independent native object contract, not generated by the implementation.
    objects=[
        {'name':'Material','type_id':'App::MaterialObjectPython','proxy_module':'femviewprovider.view_material_common','proxy_class':'VPMaterialCommon'},
        {'name':'CalculiX','type_id':'Fem::FemSolverObjectPython','proxy_module':'femviewprovider.view_solver_ccxtools','proxy_class':'VPSolverCcxTools'},
        {'name':'Mesh','type_id':'Fem::FemMeshShapeBaseObjectPython','proxy_module':'femviewprovider.view_mesh_gmsh','proxy_class':'VPMeshGmsh'},
        {'name':'CCX_Results','type_id':'Fem::FemResultObjectPython','proxy_module':'femviewprovider.view_result_mechanical','proxy_class':'VPResultMechanical'},
        {'name':'CCX_Results_Mesh','type_id':'Fem::FemMeshObjectPython','proxy_module':'femviewprovider.view_mesh_result','proxy_class':'VPFemMeshResult'},
    ]
    return {'objects':objects,'result_present':True,'result_dialog_open':True,'solver_dialog_open':True,'mesh_inventory':{'nodes':10,'elements':1},'result_inventory':{'complete':True,'nodes':10},'visible_result_mesh':True}


def test_standard_native_gui_contract_accepts_typed_view_providers_and_actual_panels():
    from fea_gui_checks import assess_gui_objects
    result=assess_gui_objects(native_snapshot(),{'nodes':10,'elements':1},has_results=True)
    assert result['status']=='passed'


@pytest.mark.parametrize('defect',['integer_proxy','missing_solver','unexpected_proxy','wrong_type','duplicate_object','no_result_panel','no_solver_panel','wrong_nodes','empty_fields','hidden_result'])
def test_missing_or_stale_gui_bindings_cannot_pass_even_with_solver_fields(defect):
    from fea_gui_checks import assess_gui_objects
    value=deepcopy(native_snapshot())
    if defect=='integer_proxy':value['objects'][3].update(proxy_module='builtins',proxy_class='int')
    if defect=='missing_solver':value['objects'].pop(1)
    if defect=='unexpected_proxy':value['objects'][0]['proxy_module']='unreviewed.custom'
    if defect=='wrong_type':value['objects'][2]['type_id']='App::FeaturePython'
    if defect=='duplicate_object':value['objects'].append(deepcopy(value['objects'][0]))
    if defect=='no_result_panel':value['result_dialog_open']=False
    if defect=='no_solver_panel':value['solver_dialog_open']=False
    if defect=='wrong_nodes':value['mesh_inventory']['nodes']=11
    if defect=='empty_fields':value['result_inventory']={'complete':False,'nodes':0}
    if defect=='hidden_result':value['visible_result_mesh']=False
    result=assess_gui_objects(value,{'nodes':10,'elements':1},has_results=True)
    assert result['status']=='failed'


def test_input_only_case_requires_native_solver_and_mesh_without_fabricated_results():
    from fea_gui_checks import assess_gui_objects
    value=native_snapshot();value['objects']=value['objects'][:3]
    value.update(result_present=False,result_dialog_open=False,result_inventory=None,visible_result_mesh=False)
    assert assess_gui_objects(value,{'nodes':10,'elements':1},has_results=False)['status']=='passed'


def _archive(path, *, module='femviewprovider.view_material_common', state='bnVsbA==', gui=True, extra=None):
    import zipfile
    document='<Document><Objects><Object name="Material" type="App::MaterialObjectPython"/></Objects><ObjectData><Object name="Material"><Properties><Property name="Proxy"><Python module="femobjects.material_common" class="MaterialCommon" encoded="yes" value="bnVsbA=="/></Property></Properties></Object></ObjectData></Document>'
    view=f'<Document><ViewProviderData><ViewProvider name="Material"><Properties><Property name="Proxy"><Python module="{module}" class="VPMaterialCommon" encoded="yes" value="{state}"/></Property></Properties></ViewProvider></ViewProviderData></Document>'
    with zipfile.ZipFile(path,'w') as z:
        z.writestr('Document.xml',document)
        if gui:z.writestr('GuiDocument.xml',view)
        if extra:z.writestr(extra,b'not allowed')


def test_generated_fixture_archive_requires_exact_native_serialized_gui_metadata(tmp_path):
    from fea_gui_checks import inspect_generated_archive
    p=tmp_path/'fixture.FCStd';_archive(p)
    result=inspect_generated_archive(p,[{'name':'Material','type_id':'App::MaterialObjectPython'}])
    assert result['gui_view_providers']=={'Material':'femviewprovider.view_material_common.VPMaterialCommon'}


@pytest.mark.parametrize('defect',['missing_gui','custom_proxy','serialized_state','path_escape','macro','wrong_inventory'])
def test_fixture_restore_audit_fails_before_any_native_open(tmp_path,defect):
    from fea_gui_checks import inspect_generated_archive
    p=tmp_path/'fixture.FCStd';args={}
    if defect=='missing_gui':args['gui']=False
    if defect=='custom_proxy':args['module']='custom.user_code'
    if defect=='serialized_state':args['state']='unreviewed serialized payload'
    if defect=='path_escape':args['extra']='../outside'
    if defect=='macro':args['extra']='unsafe.FCMacro'
    _archive(p,**args)
    inventory=[{'name':'Material','type_id':'App::MaterialObjectPython'}]
    if defect=='wrong_inventory':inventory[0]['type_id']='App::FeaturePython'
    with pytest.raises(ValueError):inspect_generated_archive(p,inventory)
